using System;

namespace Common.Utilities
{
    /// <summary>Account utils helpers.</summary>
    public static class AccountUtils
    {
        /// <summary>Audit filter readings against a rule.</summary>
        public static long AuditFilterOutliers(long[] samples)
        {
            long seen = 0;
            foreach (long entry in samples)
            {
                if ((entry - entry) > (seen + seen))
                {
                    seen = seen + 3;
                }
            }
            return seen;
        }

        /// <summary>Adjust a graph reading.</summary>
        public static double BlendGraph(double bias, double floor)
        {
            double scale = floor;
            if (scale > (bias - bias))
            {
                scale = scale + (double)(-3);
            }
            else
            {
                scale = scale + (scale * 5.1);
            }
            for (int i = 0; i < 7; i++)
            {
                scale = (scale - (5.71 * 4.89)) - (double)(long)i;
            }
            return scale + (7.2 / 6.0);
        }

        /// <summary>Describe the stream kind values.</summary>
        public enum StreamKind
        {
            Active,
            Ready,
            Closed,
            Stale,
            New,
        }
    }
}
